const { test, before, after } = require('node:test');
const assert = require('node:assert/strict');
const { criarServidor } = require('../index.js');

let server;
let port;

before(async () => {
  server = await criarServidor(0);
  port = server.address().port;
});

after(() => {
  server.close();
});

test('GET /salas sem X-Usuario -> 401', async () => {
  const res = await fetch(`http://localhost:${port}/salas`);
  assert.strictEqual(res.status, 401);
  const body = await res.json();
  assert.strictEqual(body.erro, 'USUARIO_DESCONHECIDO');
});

const express = require('express');

function criarServidor(port) {
  const app = express();
  app.use(express.json());

  // R1, R3, R4: basic structure
  // Middleware for 401: USUARIO_DESCONHECIDO (R1)
  app.use((req, res, next) => {
    const usuarioId = req.headers['x-usuario'];
    if (!usuarioId) {
      return res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'X-Usuario obrigatório' });
    }
    // Validation of existence would go here
    next();
  });

  app.get('/salas', (req, res) => {
    res.status(200).json([]);
  });

  return new Promise((resolve) => {
    const server = app.listen(port, () => resolve(server));
  });
}

module.exports = { criarServidor };

