 function criarServidor(port) {
   const app = express();
   app.use(express.json());

   // Estado do relógio em memória (apenas para MODO_TESTE)
   let relogio = '2026-10-13T09:00:00-03:00';

   if (process.env.MODO_TESTE === '1') {
